@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RegisterScreen(
  patients: List<PatientItem>,
  isLoading: Boolean,
  isSyncing: Boolean,
  syncStatusMessage: String?,
  onRefresh: () -> Unit,
  onPatientClick: (patientId: String) -> Unit,
) {
  val dateFormatter = DateTimeFormatter.ofPattern("MMM d, yyyy")

  Scaffold(
    topBar = {
      TopAppBar(
        title = {
          Column {
            Text("ANC Register", fontWeight = FontWeight.Bold)
            if (!syncStatusMessage.isNullOrBlank()) {
              Text(
                syncStatusMessage,
                style = MaterialTheme.typography.labelSmall,
                color = MaterialTheme.colorScheme.onPrimaryContainer.copy(alpha = 0.8f),
              )
            }
          }
        },
        colors = TopAppBarDefaults.topAppBarColors(
          containerColor = MaterialTheme.colorScheme.primaryContainer,
          titleContentColor = MaterialTheme.colorScheme.onPrimaryContainer,
        ),
        actions = {
          if (isSyncing) {
            CircularProgressIndicator(
              modifier = Modifier
                .padding(12.dp)
                .size(24.dp),
              strokeWidth = 2.5.dp,
              color = MaterialTheme.colorScheme.onPrimaryContainer,
            )
          } else {
            IconButton(onClick = onRefresh) {
              Icon(
                imageVector = Icons.Default.Refresh,
                contentDescription = "Sync from server",
                tint = MaterialTheme.colorScheme.onPrimaryContainer,
              )
            }
          }
        },
      )
    },
  ) { innerPadding ->
    Box(
      modifier = Modifier
        .fillMaxSize()
        .padding(innerPadding),
    ) {
      if (isLoading && patients.isEmpty()) {
        Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
          CircularProgressIndicator()
        }
      } else if (patients.isEmpty()) {
        Box(
          modifier = Modifier
            .fillMaxSize()
            .padding(24.dp),
          contentAlignment = Alignment.Center,
        ) {
          Column(horizontalAlignment = Alignment.CenterHorizontally) {
            Icon(
              imageVector = Icons.Default.Person,
              contentDescription = null,
              modifier = Modifier.size(64.dp),
              tint = MaterialTheme.colorScheme.outline,
            )
            Spacer(modifier = Modifier.height(16.dp))
            Text(
              "No pregnant patients found.",
              style = MaterialTheme.typography.titleMedium,
              color = MaterialTheme.colorScheme.outline,
            )
            Spacer(modifier = Modifier.height(8.dp))
            Text(
              "Tap the refresh button in the top bar to sync with the server.",
              style = MaterialTheme.typography.bodyMedium,
              color = MaterialTheme.colorScheme.outline,
            )
          }
        }
      } else {
        LazyColumn(
          modifier = Modifier
            .fillMaxSize()
            .padding(horizontal = 16.dp, vertical = 8.dp),
          verticalArrangement = Arrangement.spacedBy(12.dp),
        ) {
          item {
            Text(
              text = "Currently Pregnant Patients (${patients.size})",
              style = MaterialTheme.typography.labelLarge,
              color = MaterialTheme.colorScheme.secondary,
              modifier = Modifier.padding(vertical = 4.dp),
            )
          }

          items(patients, key = { it.id }) { patient ->
            PatientCard(
              patient = patient,
              dateFormatter = dateFormatter,
              onClick = { onPatientClick(patient.id) },
            )
          }
        }
      }
    }
  }
}

@Composable
fun PatientCard(
  patient: PatientItem,
  dateFormatter: DateTimeFormatter,
  onClick: () -> Unit,
) {
  Card(
    modifier = Modifier
      .fillMaxWidth()
      .clickable(onClick = onClick),
    elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
  ) {
    Row(
      modifier = Modifier
        .fillMaxWidth()
        .padding(16.dp),
      verticalAlignment = Alignment.CenterVertically,
    ) {
      Column(modifier = Modifier.weight(1f)) {
        Row(
          verticalAlignment = Alignment.CenterVertically,
          horizontalArrangement = Arrangement.SpaceBetween,
          modifier = Modifier.fillMaxWidth(),
        ) {
          Text(
            text = patient.name,
            style = MaterialTheme.typography.titleMedium,
            fontWeight = FontWeight.SemiBold,
          )
          if (patient.age != null) {
            Surface(
              color = MaterialTheme.colorScheme.secondaryContainer,
              shape = MaterialTheme.shapes.small,
            ) {
              Text(
                text = "${patient.age} yrs",
                style = MaterialTheme.typography.labelMedium,
                color = MaterialTheme.colorScheme.onSecondaryContainer,
                modifier = Modifier.padding(horizontal = 8.dp, vertical = 2.dp),
              )
            }
          }
        }

        Spacer(modifier = Modifier.height(8.dp))

        Row(verticalAlignment = Alignment.CenterVertically) {
          Icon(
            imageVector = Icons.Default.CalendarToday,
            contentDescription = null,
            modifier = Modifier.size(16.dp),
            tint = MaterialTheme.colorScheme.primary,
          )
          Spacer(modifier = Modifier.width(6.dp))
          Text(
            text = if (patient.dueDate != null) {
              "Est. Due: ${patient.dueDate.format(dateFormatter)}"
            } else {
              "Est. Due: Unknown"
            },
            style = MaterialTheme.typography.bodyMedium,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
          )
        }

        Spacer(modifier = Modifier.height(4.dp))

        Row(verticalAlignment = Alignment.CenterVertically) {
          Icon(
            imageVector = Icons.Default.PregnantWoman,
            contentDescription = null,
            modifier = Modifier.size(18.dp),
            tint = MaterialTheme.colorScheme.tertiary,
          )
          Spacer(modifier = Modifier.width(6.dp))
          Text(
            text = if (patient.gestationalWeeks != null) {
              "${patient.gestationalWeeks} weeks of pregnancy"
            } else {
              "Gestational age unknown"
            },
            style = MaterialTheme.typography.bodyMedium,
            fontWeight = FontWeight.Medium,
            color = MaterialTheme.colorScheme.tertiary,
          )
        }
      }

      Spacer(modifier = Modifier.width(8.dp))
      Icon(
        imageVector = Icons.Default.ChevronRight,
        contentDescription = null,
        tint = MaterialTheme.colorScheme.outline,
      )
    }
  }
}

