@Composable
fun PatientDetailScreen(
  patientDetail: PatientDetail?,
  isLoading: Boolean,
  onBack: () -> Unit,
  onRecordNewVisit: () -> Unit,
) {
  val dateFormatter = DateTimeFormatter.ofPattern("MMM d, yyyy")

  Scaffold(
    topBar = {
      TopAppBar(
        title = {
          Text(
            patientDetail?.patient?.name ?: "Patient Detail",
            fontWeight = FontWeight.Bold,
          )
        },
        navigationIcon = {
          IconButton(onClick = onBack) {
            Icon(
              imageVector = Icons.AutoMirrored.Filled.ArrowBack,
              contentDescription = "Back",
            )
          }
        },
        colors = TopAppBarDefaults.topAppBarColors(
          containerColor = MaterialTheme.colorScheme.primaryContainer,
          titleContentColor = MaterialTheme.colorScheme.onPrimaryContainer,
        ),
      )
    },
    floatingActionButton = {
      ExtendedFloatingActionButton(
        onClick = onRecordNewVisit,
        icon = { Icon(Icons.Default.Add, contentDescription = null) },
        text = { Text("Record New Visit") },
        containerColor = MaterialTheme.colorScheme.primary,
        contentColor = MaterialTheme.colorScheme.onPrimary,
      )
    },
  ) { innerPadding ->
    Box(
      modifier = Modifier
        .fillMaxSize()
        .padding(innerPadding),
    ) {
      if (isLoading && patientDetail == null) {
        Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
          CircularProgressIndicator()
        }
      } else if (patientDetail == null) {
        Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
          Text("Patient not found", style = MaterialTheme.typography.titleMedium)
        }
      } else {
        val patient = patientDetail.patient
        val visits = patientDetail.visits

        LazyColumn(
          modifier = Modifier
            .fillMaxSize()
            .padding(horizontal = 16.dp, vertical = 12.dp),
          verticalArrangement = Arrangement.spacedBy(16.dp),
        ) {
          // Patient summary card
          item {
            Card(
              modifier = Modifier.fillMaxWidth(),
              colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.secondaryContainer),
            ) {
              Column(modifier = Modifier.padding(16.dp)) {
                Text(
                  text = patient.name,
                  style = MaterialTheme.typography.titleLarge,
                  fontWeight = FontWeight.Bold,
                  color = MaterialTheme.colorScheme.onSecondaryContainer,
                )
                Spacer(modifier = Modifier.height(4.dp))
                Row(
                  horizontalArrangement = Arrangement.spacedBy(16.dp),
                  modifier = Modifier.fillMaxWidth(),
                ) {
                  if (patient.age != null) {
                    Text(
                      text = "Age: ${patient.age} yrs",
                      style = MaterialTheme.typography.bodyMedium,
                      color = MaterialTheme.colorScheme.onSecondaryContainer,
                    )
                  }
                  if (patient.gestationalWeeks != null) {
                    Text(
                      text = "Current: ${patient.gestationalWeeks} wks pregnant",
                      style = MaterialTheme.typography.bodyMedium,
                      fontWeight = FontWeight.SemiBold,
                      color = MaterialTheme.colorScheme.onSecondaryContainer,
                    )
                  }
                }
                if (patient.dueDate != null) {
                  Spacer(modifier = Modifier.height(4.dp))
                  Text(
                    text = "Est. Due Date: ${patient.dueDate.format(dateFormatter)}",
                    style = MaterialTheme.typography.bodyMedium,
                    color = MaterialTheme.colorScheme.onSecondaryContainer,
                  )
                }
              }
            }
          }

          item {
            Text(
              text = "Past ANC Visits (${visits.size})",
              style = MaterialTheme.typography.titleMedium,
              fontWeight = FontWeight.SemiBold,
              color = MaterialTheme.colorScheme.primary,
            )
          }

          if (visits.isEmpty()) {
            item {
              Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant),
              ) {
                Box(
                  modifier = Modifier
                    .fillMaxWidth()
                    .padding(24.dp),
                  contentAlignment = Alignment.Center,
                ) {
                  Text(
                    "No ANC visits recorded yet.",
                    style = MaterialTheme.typography.bodyMedium,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                  )
                }
              }
            }
          } else {
            items(visits, key = { it.encounterId }) { visit ->
              VisitCard(visit = visit, dateFormatter = dateFormatter)
            }
          }

          // Bottom padding so FAB does not cover content
          item {
            Spacer(modifier = Modifier.height(72.dp))
          }
        }
      }
    }
  }
}

@OptIn(ExperimentalLayoutApi::class)
@Composable
fun VisitCard(
  visit: VisitItem,
  dateFormatter: DateTimeFormatter,
) {
  val formattedDate = try {
    LocalDate.parse(visit.date.substringBefore("T")).format(dateFormatter)
  } catch (_: Exception) {
    visit.date.ifBlank { "Unknown date" }
  }

  Card(
    modifier = Modifier.fillMaxWidth(),
    elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
  ) {
    Column(modifier = Modifier.padding(16.dp)) {
      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically,
      ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
          Icon(
            imageVector = Icons.Default.CalendarMonth,
            contentDescription = null,
            tint = MaterialTheme.colorScheme.primary,
            modifier = Modifier.size(20.dp),
          )
          Spacer(modifier = Modifier.width(8.dp))
          Text(
            text = formattedDate,
            style = MaterialTheme.typography.titleMedium,
            fontWeight = FontWeight.Bold,
          )
        }

        if (visit.gestationalAgeWeeks != null) {
          Surface(
            color = MaterialTheme.colorScheme.tertiaryContainer,
            shape = MaterialTheme.shapes.small,
          ) {
            Text(
              text = "${visit.gestationalAgeWeeks} wks GA",
              style = MaterialTheme.typography.labelMedium,
              color = MaterialTheme.colorScheme.onTertiaryContainer,
              modifier = Modifier.padding(horizontal = 8.dp, vertical = 2.dp),
            )
          }
        }
      }

      HorizontalDivider(
        modifier = Modifier.padding(vertical = 10.dp),
        color = DividerDefaults.color.copy(alpha = 0.5f),
      )

      // Vital Signs
      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
      ) {
        // Weight
        Column(modifier = Modifier.weight(1f)) {
          Text(
            text = "Weight",
            style = MaterialTheme.typography.labelSmall,
            color = MaterialTheme.colorScheme.outline,
          )
          Text(
            text = visit.weight ?: "—",
            style = MaterialTheme.typography.bodyLarge,
            fontWeight = FontWeight.Medium,
          )
        }

        // Blood Pressure
        Column(modifier = Modifier.weight(1.2f)) {
          Text(
            text = "Blood Pressure",
            style = MaterialTheme.typography.labelSmall,
            color = MaterialTheme.colorScheme.outline,
          )
          Text(
            text = visit.bloodPressure ?: "—",
            style = MaterialTheme.typography.bodyLarge,
            fontWeight = FontWeight.Medium,
          )
        }

        // Hemoglobin
        Column(modifier = Modifier.weight(1.1f)) {
          Text(
            text = "Hemoglobin",
            style = MaterialTheme.typography.labelSmall,
            color = MaterialTheme.colorScheme.outline,
          )
          Text(
            text = visit.hemoglobin ?: "—",
            style = MaterialTheme.typography.bodyLarge,
            fontWeight = FontWeight.Medium,
          )
        }
      }

      // Danger signs (if recorded)
      if (visit.dangerSigns.isNotEmpty()) {
        Spacer(modifier = Modifier.height(10.dp))
        Row(verticalAlignment = Alignment.CenterVertically) {
          val hasDanger = visit.dangerSigns.any { !it.equals("None", ignoreCase = true) }
          Icon(
            imageVector = Icons.Default.Warning,
            contentDescription = null,
            tint = if (hasDanger) MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.primary,
            modifier = Modifier.size(16.dp),
          )
          Spacer(modifier = Modifier.width(6.dp))
          Text(
            text = "Danger signs: ${visit.dangerSigns.joinToString(", ")}",
            style = MaterialTheme.typography.bodyMedium,
            color = if (hasDanger) MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.onSurfaceVariant,
            fontWeight = if (hasDanger) FontWeight.SemiBold else FontWeight.Normal,
          )
        }
      }

      // Notes (if recorded)
      if (!visit.notes.isNullOrBlank()) {
        Spacer(modifier = Modifier.height(8.dp))
        Text(
          text = "Notes: ${visit.notes}",
          style = MaterialTheme.typography.bodyMedium,
          color = MaterialTheme.colorScheme.onSurfaceVariant,
        )
      }
    }
  }
}

