@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun NewVisitScreen(
  patientId: String,
  repository: AncRepository,
  onVisitSaved: () -> Unit,
  onCancel: () -> Unit,
) {
  var questionnaireJson by remember { mutableStateOf<String?>(null) }
  var isSaving by remember { mutableStateOf(false) }
  val scope = rememberCoroutineScope()

  LaunchedEffect(patientId) {
    questionnaireJson = repository.getQuestionnaireJson()
  }

  Scaffold(
    topBar = {
      TopAppBar(
        title = { Text("Record ANC Visit", fontWeight = FontWeight.Bold) },
        navigationIcon = {
          IconButton(onClick = onCancel) {
            Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Cancel")
          }
        },
        colors = TopAppBarDefaults.topAppBarColors(
          containerColor = MaterialTheme.colorScheme.primaryContainer,
          titleContentColor = MaterialTheme.colorScheme.onPrimaryContainer,
        ),
      )
    },
  ) { innerPadding ->
    Box(
      modifier = Modifier
        .fillMaxSize()
        .padding(innerPadding),
    ) {
      val json = questionnaireJson
      if (json == null || isSaving) {
        Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
          CircularProgressIndicator()
        }
      } else {
        Questionnaire(
          questionnaireJson = json,
          config = QuestionnaireConfig(
            showSubmitButton = true,
            showCancelButton = true,
            submitButtonText = "Save Visit",
          ),
          onSubmit = { getResponse ->
            scope.launch {
              try {
                isSaving = true
                val response: QuestionnaireResponse = getResponse()
                repository.saveVisit(patientId, response)
                onVisitSaved()
              } catch (_: CancellationException) {
                // Validation failed; form displays errors itself
                isSaving = false
              } catch (_: Exception) {
                isSaving = false
              }
            }
          },
          onCancel = onCancel,
        )
      }
    }
  }
}

package com.example.ancapp

import android.app.Application
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import dev.ohs.fhir.engine.sync.CurrentSyncJobStatus
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.launch

data class MainUiState(
  val patients: List<PatientItem> = emptyList(),
  val isLoading: Boolean = false,
  val isSyncing: Boolean = false,
  val syncMessage: String? = null,
)

class MainViewModel(application: Application) : AndroidViewModel(application) {
  val repository = AncRepository(application)

  private val _uiState = MutableStateFlow(MainUiState())
  val uiState = _uiState.asStateFlow()

  init {
    loadPatients()
    syncData()
  }

  fun loadPatients() {
    viewModelScope.launch {
      _uiState.value = _uiState.value.copy(isLoading = true)
      try {
        val list = repository.getPregnantPatients()
        _uiState.value = _uiState.value.copy(patients = list, isLoading = false)
      } catch (_: Exception) {
        _uiState.value = _uiState.value.copy(isLoading = false)
      }
    }
  }

  fun syncData() {
    viewModelScope.launch {
      _uiState.value = _uiState.value.copy(isSyncing = true, syncMessage = "Syncing with server...")
      try {
        val terminal = repository.sync().first {
          it is CurrentSyncJobStatus.Succeeded ||
            it is CurrentSyncJobStatus.Failed ||
            it is CurrentSyncJobStatus.Cancelled
        }
        val isSuccess = terminal is CurrentSyncJobStatus.Succeeded
        val msg = if (isSuccess) "Synced with server" else "Sync failed"
        _uiState.value = _uiState.value.copy(
          isSyncing = false,
          syncMessage = msg,
        )
        loadPatients()
      } catch (e: Exception) {
        _uiState.value = _uiState.value.copy(
          isSyncing = false,
          syncMessage = "Sync error: ${e.localizedMessage ?: "Unknown"}",
        )
        loadPatients()
      }
    }
  }
}

