class PatientDetailViewModel(application: Application) : AndroidViewModel(application) {
  val repository = AncRepository(application)

  private val _patientDetail = MutableStateFlow<PatientDetail?>(null)
  val patientDetail = _patientDetail.asStateFlow()

  private val _isLoading = MutableStateFlow(false)
  val isLoading = _isLoading.asStateFlow()

  fun loadPatient(patientId: String) {
    viewModelScope.launch {
      _isLoading.value = true
      try {
        val detail = repository.getPatientDetail(patientId)
        _patientDetail.value = detail
      } catch (_: Exception) {
        // Handle gracefully
      } finally {
        _isLoading.value = false
      }
    }
  }
}

