import androidx.navigation.navArgument
import com.example.ancapp.ui.NewVisitScreen
import com.example.ancapp.ui.PatientDetailScreen
import com.example.ancapp.ui.RegisterScreen

class MainActivity : ComponentActivity() {
  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)
    setContent {
      MaterialTheme {
        Surface(modifier = Modifier.fillMaxSize()) {
          AncApp()
        }
      }
    }
  }
}

@Composable
fun AncApp() {
  val navController = rememberNavController()
  val mainViewModel: MainViewModel = viewModel()

  NavHost(navController = navController, startDestination = "register") {
    composable("register") {
      val uiState by mainViewModel.uiState.collectAsState()
      RegisterScreen(
        patients = uiState.patients,
        isLoading = uiState.isLoading,
        isSyncing = uiState.isSyncing,
        syncStatusMessage = uiState.syncMessage,
        onRefresh = { mainViewModel.syncData() },
        onPatientClick = { patientId ->
          navController.navigate("patient_detail/$patientId")
        },
      )
    }

    composable(
      route = "patient_detail/{patientId}",
      arguments = listOf(navArgument("patientId") { type = NavType.StringType }),
    ) { backStackEntry ->
      val patientId = backStackEntry.arguments?.getString("patientId") ?: ""
      val detailViewModel: PatientDetailViewModel = viewModel(key = "detail_$patientId")
      val detail by detailViewModel.patientDetail.collectAsState()
      val isLoading by detailViewModel.isLoading.collectAsState()

      val lifecycleOwner = LocalLifecycleOwner.current
      DisposableEffect(lifecycleOwner, patientId) {
        val observer = LifecycleEventObserver { _, event ->
          if (event == Lifecycle.Event.ON_RESUME) {
            detailViewModel.loadPatient(patientId)
          }
        }
        lifecycleOwner.lifecycle.addObserver(observer)
        onDispose {
          lifecycleOwner.lifecycle.removeObserver(observer)
        }
      }

      PatientDetailScreen(
        patientDetail = detail,
        isLoading = isLoading,
        onBack = { navController.popBackStack() },
        onRecordNewVisit = {
          navController.navigate("new_visit/$patientId")
        },
      )
    }

    composable(
      route = "new_visit/{patientId}",
      arguments = listOf(navArgument("patientId") { type = NavType.StringType }),
    ) { backStackEntry ->
      val patientId = backStackEntry.arguments?.getString("patientId") ?: ""
      NewVisitScreen(
        patientId = patientId,
        repository = mainViewModel.repository,
        onVisitSaved = {
          mainViewModel.loadPatients()
          navController.popBackStack()
        },
        onCancel = {
          navController.popBackStack()
        },
      )
    }
  }
}

